package com.muthumol.player.dummy;
import android.content.Context;import android.graphics.*;import android.view.View;import java.util.concurrent.*;
/** Bounded decoded artwork. Online lookups belong to ArtworkStore, never the UI thread. */
final class PosterArtView extends View {
 private static final ExecutorService DECODER=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"Artwork decode");t.setDaemon(true);return t;});
 private final int decodeWidth,decodeHeight;private final Paint paint=new Paint(3);private Bitmap bitmap,previous;private android.animation.ValueAnimator fade,drift;private float driftFraction;private float blend=1;String displayedIdentity="";private String key="",title="YOUR CINEMA";private int accent=Ui.MENU_COLORS[0],generation;boolean cinematic;
 PosterArtView(Context c){this(c,1920,1080);}PosterArtView(Context c,int w,int h){super(c);decodeWidth=w;decodeHeight=h;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}
 void show(Movie m,int color){String name=m==null?"YOUR CINEMA":MediaTitle.parse(m.title).name;boolean changed=accent!=color||!title.equals(name);accent=color;title=name;displayedIdentity=m==null?"":m.cacheIdentity();ArtworkStore.Entry online=ArtworkStore.get(getContext()).cached(m);String path=online==null?"":online.path;String next=m==null?"":online==null?"empty:"+title:path+":"+decodeWidth+":"+decodeHeight;if(next.equals(key)){if(changed)invalidate();return;}key=next;if(fade!=null)fade.cancel();previous=null;blend=1;int token=++generation;if(m==null||path.isEmpty()){bitmap=null;invalidate();return;}invalidate();
  DECODER.execute(()->{Bitmap result=null;try{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(path,o);if(o.outWidth>0&&o.outHeight>0&&(long)o.outWidth*o.outHeight<=32000000){o.inSampleSize=1;while(o.outWidth/o.inSampleSize>decodeWidth||o.outHeight/o.inSampleSize>decodeHeight)o.inSampleSize*=2;o.inJustDecodeBounds=false;o.inPreferredConfig=Bitmap.Config.RGB_565;result=BitmapFactory.decodeFile(path,o);}}catch(Exception|OutOfMemoryError ignored){}final Bitmap decoded=result;post(()->{if(token==generation){boolean animate=cinematic&&bitmap!=null&&decoded!=null&&isAttachedToWindow()&&android.provider.Settings.Global.getFloat(getContext().getContentResolver(),android.provider.Settings.Global.ANIMATOR_DURATION_SCALE,1)>0;previous=animate?bitmap:null;bitmap=decoded;startDrift();blend=animate?0:1;if(animate){fade=android.animation.ValueAnimator.ofFloat(0,1);fade.setDuration(600);fade.addUpdateListener(a->{blend=(float)a.getAnimatedValue();invalidate();});fade.addListener(new android.animation.AnimatorListenerAdapter(){public void onAnimationEnd(android.animation.Animator a){previous=null;blend=1;invalidate();}});fade.start();}invalidate();}else if(decoded!=null)decoded.recycle();});});
 }
 @Override protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),radius=Ui.dp(getContext(),12);int save=c.save();if(!cinematic){Path clip=new Path();clip.addRoundRect(new RectF(0,0,w,h),radius,radius,Path.Direction.CW);c.clipPath(clip);}paint.setShader(new LinearGradient(0,0,w,h,new int[]{TmStyle.RAISED,TmStyle.BACKGROUND},null,Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,paint);paint.setShader(null);
  if(bitmap!=null){if(previous!=null)drawImage(c,previous,w,h,255);drawImage(c,bitmap,w,h,previous==null?255:(int)(255*blend));}
  else if(!cinematic){paint.setColor(0xff697991);paint.setTypeface(Typeface.DEFAULT_BOLD);paint.setTextSize(Ui.dp(getContext(),26));String initial=title.isEmpty()?"▶":title.substring(0,title.offsetByCodePoints(0,1)).toUpperCase(java.util.Locale.ROOT);c.drawText(initial,(w-paint.measureText(initial))/2,h*.48f,paint);paint.setColor(0xff9aa6b8);paint.setTextSize(Ui.dp(getContext(),8));String label="COVER";c.drawText(label,(w-paint.measureText(label))/2,h*.68f,paint);}
  if(cinematic){paint.setShader(new LinearGradient(0,0,w,0,new int[]{0xff0c0e10,0xdd0c0e10,0x100c0e10},new float[]{0,.48f,1},Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,paint);paint.setShader(new LinearGradient(0,0,0,h,new int[]{0x100c0e10,0x080c0e10,0xff0c0e10},new float[]{0,.36f,1},Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,paint);paint.setShader(null);}c.restoreToCount(save);
 }
 private void drawImage(Canvas c,Bitmap image,float w,float h,int alpha){float scale=Math.max(w/image.getWidth(),h/image.getHeight())*(cinematic?1.04f+.025f*driftFraction:1);float bw=image.getWidth()*scale,bh=image.getHeight()*scale,left=(w-bw)/2+(cinematic?(driftFraction-.5f)*w*.018f:0),top=(h-bh)/2;paint.setAlpha(alpha);c.drawBitmap(image,null,new RectF(left,top,left+bw,top+bh),paint);paint.setAlpha(255);}
 /** Small background blur, produced once on the decoder worker, independent of display resolution. */
 static Bitmap frost(Bitmap original){int w=96,h=Math.max(48,Math.min(144,96*original.getHeight()/original.getWidth()));Bitmap small=Bitmap.createScaledBitmap(original,w,h,true);int[] src=new int[w*h],out=new int[w*h];small.getPixels(src,0,w,0,0,w,h);if(small!=original)small.recycle();int radius=6;
  for(int pass=0;pass<3;pass++){
   for(int y=0;y<h;y++){int red=0,green=0,blue=0;for(int k=-radius;k<=radius;k++){int color=src[y*w+Math.max(0,Math.min(w-1,k))];red+=(color>>16)&255;green+=(color>>8)&255;blue+=color&255;}for(int x=0;x<w;x++){out[y*w+x]=0xff000000|((red/13)<<16)|((green/13)<<8)|(blue/13);int a=src[y*w+Math.max(0,x-radius)],b=src[y*w+Math.min(w-1,x+radius+1)];red+=((b>>16)&255)-((a>>16)&255);green+=((b>>8)&255)-((a>>8)&255);blue+=(b&255)-(a&255);}}
   for(int x=0;x<w;x++){int red=0,green=0,blue=0;for(int k=-radius;k<=radius;k++){int color=out[Math.max(0,Math.min(h-1,k))*w+x];red+=(color>>16)&255;green+=(color>>8)&255;blue+=color&255;}for(int y=0;y<h;y++){src[y*w+x]=0xff000000|((red/13)<<16)|((green/13)<<8)|(blue/13);int a=out[Math.max(0,y-radius)*w+x],b=out[Math.min(h-1,y+radius+1)*w+x];red+=((b>>16)&255)-((a>>16)&255);green+=((b>>8)&255)-((a>>8)&255);blue+=(b&255)-(a&255);}}
  }
  return Bitmap.createBitmap(src,w,h,Bitmap.Config.ARGB_8888);
 }
 void startDrift(){if(!cinematic||drift!=null||!TvMotion.enabled(this)||!isAttachedToWindow()||getWindowVisibility()!=VISIBLE)return;drift=android.animation.ValueAnimator.ofFloat(0,1);drift.setDuration(18000);drift.setRepeatCount(-1);drift.setRepeatMode(android.animation.ValueAnimator.REVERSE);drift.addUpdateListener(a->{driftFraction=(float)a.getAnimatedValue();invalidate();});drift.start();}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();startDrift();}
 @Override protected void onWindowVisibilityChanged(int visibility){super.onWindowVisibilityChanged(visibility);if(visibility==VISIBLE)startDrift();else if(drift!=null){drift.cancel();drift=null;}}
 @Override protected void onDetachedFromWindow(){if(fade!=null)fade.cancel();if(drift!=null){drift.cancel();drift=null;}previous=null;super.onDetachedFromWindow();}

}

